def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Separate the nonzero tiles, which are divided by zero-valued gutters.
    seen = set()
    tiles = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            y0 = min(y for y, x in cells)
            y1 = max(y for y, x in cells)
            x0 = min(x for y, x in cells)
            x1 = max(x for y, x in cells)
            th, tw = y1 - y0 + 1, x1 - x0 + 1

            if (th, tw) == (3, 3):
                offsets = [(1, 1)]
            elif (th, tw) == (5, 5):
                offsets = [(dy, dx) for dy in (1, 2, 3) for dx in (1, 2, 3)]
            else:
                continue

            marker = grid[y0 + offsets[0][0]][x0 + offsets[0][1]]
            tiles.append((y0, x0, th, tw, marker, offsets))

    if not tiles:
        return out

    # The most frequent tile-interior color is the ordinary, unconnected one.
    counts = {}
    for tile in tiles:
        counts[tile[4]] = counts.get(tile[4], 0) + 1
    base = max(counts, key=counts.get)

    def draw_line(y1, x1, y2, x2, color):
        steps = max(abs(y2 - y1), abs(x2 - x1))
        if steps == 0:
            return
        for k in range(steps + 1):
            y = y1 + (y2 - y1) * k // steps
            x = x1 + (x2 - x1) * k // steps
            if out[y][x] == 0:
                out[y][x] = color

    colors = set(t[4] for t in tiles) - {base}
    for color in colors:
        group = [t for t in tiles if t[4] == color]

        # Connect matching tiles in the same tile row.
        rows = {}
        for t in group:
            rows.setdefault(t[0], []).append(t)
        for row_tiles in rows.values():
            row_tiles.sort(key=lambda t: t[1])
            for a, b in zip(row_tiles, row_tiles[1:]):
                for dy, dx in a[5]:
                    draw_line(a[0] + dy, a[1] + dx,
                              b[0] + dy, b[1] + dx, color)

        # Connect matching tiles in the same tile column.
        cols = {}
        for t in group:
            cols.setdefault(t[1], []).append(t)
        for col_tiles in cols.values():
            col_tiles.sort(key=lambda t: t[0])
            for a, b in zip(col_tiles, col_tiles[1:]):
                for dy, dx in a[5]:
                    draw_line(a[0] + dy, a[1] + dx,
                              b[0] + dy, b[1] + dx, color)

    return out
